    '  const tipo = form?.elements?.namedItem("tipoInmueble[]");',
    '  const muni = form?.elements?.namedItem("municipio[]");',
    '  if (!form || !tipo || !muni) return { ok: false };',
    '  tipo.value = "piso";',
